local function FadeElement(element, prop, goal, duration)
    TweenService:Create(element, TweenInfo.new(duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {[prop] = goal}):Play()
end

local function handleKeyResponse(response)
    if response.valid then
        return true, "Verified"
    end

    local err = response.error or "UNKNOWN_ERROR"

    if err == "KEY_INVALID" then return false, "Invalid Key"
    elseif err == "KEY_EXPIRED" then return false, "Key Expired"
    elseif err == "KEY_REVOKED" then return false, "Key Revoked"
    elseif err == "HWID_MISMATCH" then return false, "HWID Mismatch"
    elseif err == "HWID_BANNED" then 
        Player:Kick("You are hardware banned.")
        return false, "Banned"
    elseif err == "ALREADY_USED" then return false, "Key Already Used"
    elseif err == "RATE_LIMITED" then return false, "Rate Limited"
    elseif err == "SERVICE_UNAVAILABLE" then return false, "Service Down"
    elseif err == "INVALID_REQUEST" then return false, "Invalid Request"
    elseif err == "MISSING_FIELDS" then return false, "Missing Data"
    elseif err == "UNKNOWN_ERROR" then return false, "Unknown Error"
    else return false, tostring(err)
    end
end

local isClosing = false
local isVerified = false

local originalTitleText = '<font color="rgb(150,150,150)">N</font><font color="rgb(220,220,220)">exa</font><font color="rgb(255,60,60)">S</font><font color="rgb(220,220,220)">cripts</font>'

local function processVerification(keyToVerify)
    if isVerified or isClosing then return end
    
    task.spawn(function()
        VerifyBtn.Text = "Checking..."
        
        local result = Junkie.check_key(keyToVerify)
        local successFlag, msg = handleKeyResponse(result)
        
        if successFlag then
            isVerified = true
            getgenv().SCRIPT_KEY = keyToVerify
            saveKey(keyToVerify)
            SuccessSound:Play()
            
            FadeElement(KeyInput, "BackgroundTransparency", 1, 0.4)
            FadeElement(KeyInput, "TextTransparency", 1, 0.4)
            FadeElement(InputStroke, "Transparency", 1, 0.4)
            
            FadeElement(GetKeyBtn, "BackgroundTransparency", 1, 0.4)
            FadeElement(GetKeyBtn, "TextTransparency", 1, 0.4)
            
            FadeElement(VerifyBtn, "BackgroundTransparency", 1, 0.4)
            FadeElement(VerifyBtn, "TextTransparency", 1, 0.4)
            
            Title.Text = '<font color="rgb(80,255,80)">Verified</font>'
            
            for _, p in ipairs(activeParticles) do
                TweenService:Create(p.gui, TweenInfo.new(0.5), {BackgroundColor3 = Color3.fromRGB(80, 255, 80)}):Play()
            end
            
            task.wait(2)
            
            isClosing = true
            
            TweenService:Create(Blur, TweenInfo.new(0.8, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = 0}):Play()
            TweenService:Create(Title, TweenInfo.new(0.6, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Position = UDim2.new(0.5, -200 * scale, 0.5, 0)}):Play()
            
            FadeElement(MainFrame, "BackgroundTransparency", 1, 0.8)
            FadeElement(DottedPattern, "ImageTransparency", 1, 0.8)
            FadeElement(Title, "TextTransparency", 1, 0.6)
            FadeElement(CloseBtn, "TextTransparency", 1, 0.4)
            
            FadeElement(Avatar, "ImageTransparency", 1, 0.4)
            FadeElement(Avatar, "BackgroundTransparency", 1, 0.4)
            FadeElement(AvatarStroke, "Transparency", 1, 0.4)
            FadeElement(UserNameLbl, "TextTransparency", 1, 0.4)
            FadeElement(UserIdLbl, "TextTransparency", 1, 0.4)
            
            for _, p in ipairs(activeParticles) do
                FadeElement(p.gui, "BackgroundTransparency", 1, 0.6)
            end
            
            task.wait(0.8)
            if renderConnection then
                renderConnection:Disconnect()
            end
            Blur:Destroy()
            NexaGui:Destroy()
        else
            ErrorSound:Play()
            VerifyBtn.Text = "Verify key"
            KeyInput.Text = ""
            
            Title.Text = '<font color="rgb(255,80,80)">' .. msg .. '</font>'
            
            local originalColor = KeyInput.BackgroundColor3
            TweenService:Create(KeyInput, TweenInfo.new(0.1), {BackgroundColor3 = Color3.fromRGB(100, 20, 20)}):Play()
            task.wait(2)
            if not isClosing and not isVerified then
                TweenService:Create(KeyInput, TweenInfo.new(0.2), {BackgroundColor3 = originalColor}):Play()
                Title.Text = originalTitleText
            end
        end
    end)
end

